SELECT a.session_id, a.scene_id, b.scene_name, a.context_id, a.bot_id, a.tenant_id, c.bot_name FROM bt_chat_scene_process a LEFT JOIN bt_bot_scene b ON a.scene_id = b.scene_id AND a.tenant_id = b.tenant_id LEFT JOIN bt_bot c ON a.bot_id = c.bot_id AND a.tenant_id = c.tenant_id WHERE b.status_cd = '00A' AND b.scene_status = '1' AND c.status_cd = '00A' AND EXISTS(SELECT 1 FROM bt_bot_scene_rel r WHERE c.bot_id = r.bot_id AND c.tenant_id = r.tenant_id AND b.scene_id = r.scene_id AND r.status_cd = '00A')
AND a.tenant_id = #{tenantId}
