ORDER BY a.created_time DESC 3

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_chat_scene_process a
WHERE status_cd = '00A'
  AND chat_status = '1'
  AND session_id = #{dto.sessionId}
  AND tenant_id = #{dto.tenantId}
